contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(c.owner() == address(this), "not owner");
        require(_value == 0, "value must be zero for rejecting target");
        require(address(this).balance >= 0);
        uint balBefore = address(c).balance;
        // The target is this test contract, whose receive() always reverts,
        // so the low-level call is guaranteed to fail.
        bool reverted;
        c.sendMoney(address(this), _value, ""); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint balAfter = address(c).balance;
        // Rule: even when the target's call fails, sendMoney must not revert
        // and C must still have forwarded exactly _value wei to the target.
        assert(!reverted && balBefore >= _value && balBefore - balAfter == _value);
    }
    receive() external payable {
        revert("target rejects funds");
    }
}

